test('Forest paints density with a stable tool, target density and opacity-once-per-stroke; undo restores ground',async()=>{$('mode2d').click();$('new').click();$('world-size').value='128';doc.querySelector('[data-shape="flat"]').click();$('newdialog').close('generate');clickTool('paint');doc.querySelector('[data-material="4"]').click();assert.equal($('forest-settings').hidden,false);assert.equal(doc.querySelector('[data-tool="paint"]').getAttribute('aria-pressed'),'true');doc.querySelector('[data-brush="hard"]').click();$('forest-density').value='80';$('opacity').value='50';let before=await state();pointer('pointerdown');for(let j=0;j<12;j++)pointer('pointermove');pointer('pointerup');let after=await state();assert.equal(after.version,9);assert.ok(Math.abs(Math.max(...after.forest)-.4)<.0001);assert.deepEqual(after.paintAlpha,before.paintAlpha);assert.deepEqual(after.heights,before.heights);assert.ok(doc.querySelector('[data-layer="forests"]'));assert.ok([...$('erase-target').options].some(o=>o.value==='forests'));$('undo').click();assert.deepEqual((await state()).forest,before.forest);$('redo').click();assert.deepEqual((await state()).forest,after.forest);assert.equal(doc.querySelectorAll('[data-tool]').length,8);});
