test('Space left-drag pans 3D even off terrain, without orbiting or editing',async()=>{flatTestWorld();$('mode3d').click();$('orbit-reset').click();clickTool('raise');const before=await state();moves=[];key(' ',{code:'Space'});event3('pointerdown',{x:0,y:0});let initial=moves[0];moves=[];event3('pointermove',{x:60,y:30});let shifted=moves[0];event3('pointerup',{x:60,y:30});releaseSpace();assert.ok(initial&&shifted);assert.ok(Math.abs(shifted[0]-initial[0]-60)<.01);assert.ok(Math.abs(shifted[1]-initial[1]-30)<.01);assert.deepEqual(await state(),before);$('mode2d').click();});
