test('earthen palette lists eight ground swatches with accessible names, Forest separate, four named footprints',()=>{clickTool('paint');assert.deepEqual([...doc.querySelectorAll('#palette [data-material]')].map(e=>+e.dataset.material),[1,6,7,3,8,9,2,5]);for(const b of doc.querySelectorAll('[data-material]'))assert.ok(b.getAttribute('aria-label')&&b.title,b.dataset.material);assert.equal(doc.querySelectorAll('#palette .material-family').length,0);doc.querySelector('[data-brush="coast"]').click();assert.equal($('brush-name').textContent,'Coastline');for(const b of doc.querySelectorAll('[data-brush]'))assert.ok(b.getAttribute('aria-label'));assert.ok(doc.querySelector('#forest-paint [data-material="4"]'));assert.ok(doc.querySelector('[data-brush="grain"]'));assert.equal(doc.querySelectorAll('[data-brush]').length,4);doc.querySelector('[data-brush="grain"]').click();assert.match($('paint-status').textContent,/Grain/);assert.equal(doc.querySelectorAll('[data-tool]').length,8);});
test('earthen material coverage paints, mixes once per stroke, erases, and restores through undo',async()=>{flatTestWorld();clickTool('paint');doc.querySelector('[data-brush="hard"]').click();$('opacity').value='50';doc.querySelector('[data-material="7"]').click();const before=await state();pointer('pointerdown');for(let i=0;i<5;i++)pointer('pointermove');pointer('pointerup');const clay=await state();assert.equal(clay.version,9);assert.ok(clay.surfaceMaterials.length>0);let bytes=Uint8Array.from(atob(clay.surfaceMaterials),c=>c.charCodeAt(0)),cell=64*128+64;assert.ok(bytes[cell*8+5]>=127&&bytes[cell*8+5]<=128);assert.deepEqual(clay.heights,before.heights);assert.deepEqual(clay.forest,before.forest);doc.querySelector('[data-material="8"]').click();pointer('pointerdown');pointer('pointerup');const mixed=await state();bytes=Uint8Array.from(atob(mixed.surfaceMaterials),c=>c.charCodeAt(0));assert.ok(bytes[cell*8+5]>0&&bytes[cell*8+6]>0);$('undo').click();assert.equal((await state()).surfaceMaterials,clay.surfaceMaterials);$('redo').click();assert.equal((await state()).surfaceMaterials,mixed.surfaceMaterials);eraseTarget('surface');$('opacity').value='100';pointer('pointerdown');pointer('pointerup');const erased=await state();bytes=erased.surfaceMaterials?Uint8Array.from(atob(erased.surfaceMaterials),c=>c.charCodeAt(0)):new Uint8Array(128*128*8);assert.ok([...bytes.slice(cell*8,cell*8+8)].every(v=>v===0));assert.deepEqual(erased.heights,before.heights);});
