test('the height range bounds Raise and Lower, saves with the project and is undoable',async()=>{clickTool('raise');assert.equal($('height-floor').value,'20');assert.equal($('height-ceiling').value,'190');
 const before=await state();assert.equal(before.floor,20);assert.equal(before.ceiling,190);
 $('height-ceiling').dispatchEvent(new w.Event('pointerdown'));$('height-ceiling').value='150';$('height-ceiling').dispatchEvent(new w.Event('input'));assert.equal((await state()).ceiling,150);assert.equal($('target').max,'150');
 // keeps a minimum gap of 30 blocks
 $('height-floor').value='140';$('height-floor').dispatchEvent(new w.Event('input'));assert.equal((await state()).floor,120);assert.equal((await state()).ceiling,150);
 $('undo').click();const restored=await state();assert.equal(restored.floor,20);assert.equal(restored.ceiling,190);});
test('Raise strokes keep building with Strength and never pass the ceiling',async()=>{clickTool('raise');$('size').value='30';$('size').dispatchEvent(new w.Event('input'));$('strength').value='8';$('strength').dispatchEvent(new w.Event('input'));
 const before=await state();pointer('pointerdown',512,380);for(let k=0;k<60;k++)pointer('pointermove',512+(k%2)*4,380);pointer('pointerup',512,380);const after=await state();
 let added=0;for(let i=0;i<after.heights.length;i++)added=Math.max(added,after.heights[i]-before.heights[i]);assert.ok(added>4,`one long scrub builds more than the old 3-block cap (${added})`);
 assert.ok(after.heights.every((v,i)=>v<=Math.max(190,before.heights[i])+1e-6),'no cell is raised past the ceiling');$('undo').click();});
test('D/E adjust Strength (1% below 10%, 5% above) and River carve depth without changing tool or terrain',async()=>{const before=await state();
 clickTool('raise');$('strength').value='8';$('strength').dispatchEvent(new w.Event('input'));key('e');assert.equal($('strength').value,'9');assert.equal($('strengthout').value,'9%');key('e');key('e');assert.equal($('strength').value,'15','5% steps from 10%');key('d');assert.equal($('strength').value,'10');key('d');assert.equal($('strength').value,'9','1% steps at and below 10%');key('D',{shiftKey:true});assert.equal($('strength').value,'5','Shift takes four steps');for(let k=0;k<10;k++)key('d');assert.equal($('strength').value,'1','clamped at 1%');$('strength').value='8';$('strength').dispatchEvent(new w.Event('input'));
 clickTool('smooth');$('strength').value='35';$('strength').dispatchEvent(new w.Event('input'));key('e');assert.equal($('strength').value,'40');key('d');assert.equal($('strength').value,'35');
 clickTool('river');$('wand-depth').value='1.5';$('wand-depth').dispatchEvent(new w.Event('input'));key('e');assert.equal($('wand-depth').value,'1.75');key('d');assert.equal($('wand-depth').value,'1.5');
 assert.equal(doc.querySelector('[data-tool="river"]').getAttribute('aria-pressed'),'true');assert.deepEqual((await state()).heights,before.heights);});

test('Shift + River dries a stretch: removes its creek water and springs but keeps the channel',async()=>{clickTool('river');pointer('pointerdown',300,520);for(let k=1;k<=20;k++)pointer('pointermove',300+k*6,520+k*2);pointer('pointerup',420,560);
 const carved=await state();assert.ok(carved.routes.length>0);
 const shift={shiftKey:true};$('map').onpointerdown(new w.MouseEvent('pointerdown',{clientX:300,clientY:520,button:0,bubbles:true,...shift}));for(let k=1;k<=20;k++)$('map').onpointermove(new w.MouseEvent('pointermove',{clientX:300+k*6,clientY:520+k*2,button:0,bubbles:true,...shift}));$('map').onpointerup(new w.MouseEvent('pointerup',{clientX:420,clientY:560,button:0,bubbles:true,...shift}));
 const dried=await state();assert.equal(dried.routes.length,carved.routes.length-1,'the creek is gone');assert.deepEqual(dried.heights,carved.heights,'the channel stays');assert.ok(!(dried.springs||[]).length);
 $('undo').click();$('undo').click();});
test('Smooth spikes lowers thin walls across the map in one undoable step and respects a locked Relief',async()=>{const s=await state(),n=s.size,h=s.heights.slice();for(let x=20;x<60;x++)h[40*n+x]=Math.min(255,h[40*n+x]+90);
 Object.defineProperty($('file'),'files',{configurable:true,value:[{name:'spiky.json',size:1000,text:async()=>JSON.stringify({...s,heights:h})}]});await $('file').onchange();
 const before=await state();$('smooth-spikes').click();const after=await state();assert.ok(after.heights.some((v,i)=>v<before.heights[i]-50),'the wall came down');
 $('undo').click();assert.deepEqual((await state()).heights,before.heights,'one undo restores it');
 const lock=()=>doc.querySelector('[data-layer="elevation"][data-action="locked"]');lock().click();$('smooth-spikes').click();assert.deepEqual((await state()).heights,before.heights,'locked Relief is protected');lock().click();});

test('Pan tool is removed; H selects nothing and Space still pans',()=>{assert.equal(doc.querySelector('[data-tool="pan"]'),null);clickTool('raise');key('h');key('H');assert.equal(doc.querySelector('[data-tool="raise"]').getAttribute('aria-pressed'),'true');});
test('two-finger touch drag pans without editing; a touch that started a stroke is undone',async()=>{flatTestWorld();$('fit').click();clickTool('raise');const before=await state(),redoDisabled=$('redo').disabled;draws=[];touch('pointerdown',1,512,380);touch('pointerdown',2,560,380);touch('pointermove',1,572,410);touch('pointermove',2,620,410);touch('pointerup',1,572,410);touch('pointerup',2,620,410);assert.deepEqual((await state()).heights,before.heights);assert.equal($('redo').disabled,redoDisabled);const mapDraw=draws.filter(a=>a.length===5&&Math.abs(a[3]-633)<.01).at(-1);assert.ok(mapDraw);assert.ok(Math.abs(mapDraw[1]-(195.5+60))<.01,String(mapDraw[1]));assert.equal(doc.querySelector('[data-tool="raise"]').getAttribute('aria-pressed'),'true');touch('pointerdown',3,512,380);touch('pointerup',3,512,380);assert.notDeepEqual((await state()).heights,before.heights);});
test('lifting and replacing one finger keeps two-finger pan smooth',async()=>{flatTestWorld();$('fit').click();clickTool('raise');const before=await state();draws=[];touch('pointerdown',1,500,380);touch('pointerdown',2,540,380);touch('pointerup',2,540,380);touch('pointerdown',4,540,380);touch('pointermove',1,530,380);touch('pointermove',4,570,380);touch('pointerup',1,530,380);touch('pointerup',4,570,380);assert.deepEqual((await state()).heights,before.heights);const mapDraw=draws.filter(a=>a.length===5&&Math.abs(a[3]-633)<.01).at(-1);assert.ok(Math.abs(mapDraw[1]-(195.5+30))<.01,String(mapDraw[1]));});
test('dials block sits under the tools and shows each tool\'s D/E dial',()=>{const panel=$('tool-settings'),ids=[...panel.children].map(e=>e.id).filter(Boolean);assert.ok(ids.indexOf('brush-controls')>-1&&ids.indexOf('brush-controls')<ids.indexOf('brush-settings'));const dial={raise:'strength-label',lower:'strength-label',smooth:'strength-label',flatten:'target-label',paint:'opacity-label',path:'opacity-label',river:'wand-depth'};const visible=id=>{let el=id==='wand-depth'?$(id).closest('label'):$(id);for(;el&&el!==panel;el=el.parentElement)if(el.hidden)return false;return true;};for(const[t,id]of Object.entries(dial)){clickTool(t);assert.ok($('brush-controls').contains($(id)),t);assert.ok(visible(id),t);for(const other of new Set(Object.values(dial)))if(other!==id&&!(t==='flatten'&&other==='strength-label'))assert.equal(visible(other),false,`${t} hides ${other}`);}clickTool('land');for(const id of new Set(Object.values(dial)))assert.equal(visible(id),false,'land '+id);assert.equal(doc.querySelectorAll('#tools kbd.tool-key').length,8);assert.deepEqual([...doc.querySelectorAll('#tools kbd.tool-key')].map(k=>k.textContent),['R','L','Q','F','V','C','J','P']);});
test('D/E on Land changes no dial',async()=>{clickTool('land');const ids=['strength','target','opacity','wand-depth'],v=ids.map(i=>$(i).value),b=await state();key('d');key('e');key('E',{shiftKey:true});assert.deepEqual(ids.map(i=>$(i).value),v);assert.deepEqual(await state(),b);});
